function alertPrecision({ baseRate, truePositiveRate, falsePositiveRate }) {
  const real = baseRate * truePositiveRate;
  const fake = (1 - baseRate) * falsePositiveRate;
  if (real + fake === 0) return 0;
  return Math.round((real / (real + fake)) * 1000) / 10;
}

