function expectedBeeps(total, baseRate, truePositiveRate, falsePositiveRate) {
  const fakes = total * baseRate;
  const genuine = total - fakes;
  return {
    real: Math.round(fakes * truePositiveRate),
    falseAlarms: Math.round(genuine * falsePositiveRate),
  };
}

function gapsByGroup(groups) {
  return groups.map((g) => {
    const treated = Math.round((g.treatedHit / g.treatedTotal) * 100);
    const other = Math.round((g.otherHit / g.otherTotal) * 100);
    return treated - other;
  });
}

function precisionCurve(baseRates, truePositiveRate, falsePositiveRate) {
  return baseRates.map((b) => {
    const real = b * truePositiveRate;
    const fake = (1 - b) * falsePositiveRate;
    if (real + fake === 0) return 0;
    return Math.round((real / (real + fake)) * 100);
  });
}
